// UnmarshalJSON implements json.Unmarshaler.
func (bs *wireBlocks) UnmarshalJSON(data []byte) error {
	*bs = nil
	dec := json.NewDecoder(bytes.NewReader(data))
	if tok, err := dec.Token(); err != nil || tok != json.Delim('[') {
		return nil
	}
	for i := 0; dec.More(); i++ {
		var b wireBlock
		// A type mismatch (a numeric id, say) leaves the other fields set and
		// consumes the element; only a syntax error stops the scan, and the
		// line was already validated as JSON.
		if err := dec.Decode(&b); err != nil {
			var te *json.UnmarshalTypeError
			if !errors.As(err, &te) {
				return nil
			}
		}
